import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private String dbUrl;
    private String dbUser;
    private String dbPass;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        dbUrl = System.getenv("REPORT_DB_URL");
        dbUser = System.getenv("REPORT_DB_USER");
        dbPass = System.getenv("REPORT_DB_PASS");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String dateRange = req.getParameter("range");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Sanitize format parameter
        if (format != null && !format.matches("^(pdf|csv|json)$")) {
            format = "json";
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass)) {
            // Build query with date range filter
            String query = "SELECT r.id, r.title, r.created_at, r.data, u.email " +
                          "FROM reports r JOIN users u ON r.author_id = u.id " +
                          "WHERE r.id = " + reportId;

            if (dateRange != null && !dateRange.isEmpty()) {
                query += " AND r.created_at >= '" + dateRange + "'";
            }

            log.info("Executing report query for id: " + reportId.substring(0, Math.min(reportId.length(), 8)));

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("title", rs.getString("title"));
                row.put("created_at", rs.getString("created_at"));
                row.put("data", rs.getString("data"));
                row.put("author_email", rs.getString("email"));
                results.put(row);
            }

            JSONObject response = new JSONObject();
            response.put("status", "ok");
            response.put("results", results);
            response.put("count", results.length());
            out.print(response.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            JSONObject error = new JSONObject();
            error.put("status", "error");
            error.put("message", "Report retrieval failed");
            out.print(error.toString());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk report generation endpoint
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }

        JSONObject payload = new JSONObject(body.toString());
        JSONArray ids = payload.getJSONArray("report_ids");
        String filterExpr = payload.optString("filter", "");

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(dbUrl, dbUser, dbPass)) {
            JSONArray allResults = new JSONArray();

            for (int i = 0; i < ids.length(); i++) {
                String rid = ids.getString(i);
                String q = "SELECT * FROM reports WHERE id = " + rid;
                if (!filterExpr.isEmpty()) {
                    q += " AND (" + filterExpr + ")";
                }

                Statement stmt = conn.createStatement();
                ResultSet rs = stmt.executeQuery(q);
                while (rs.next()) {
                    JSONObject row = new JSONObject();
                    row.put("id", rs.getInt("id"));
                    row.put("title", rs.getString("title"));
                    allResults.put(row);
                }
            }

            out.print(new JSONObject().put("results", allResults).toString());
        } catch (SQLException e) {
            out.print(new JSONObject().put("error", "bulk query failed").toString());
        }
    }
}
